@spec vm_retune_spec  src=tests/specs/vm_retune_spec.lua  loc=288  cases=15
@exercises tuning (tuning), trackerView (h.vm), editCursor (h.ec), configManager (h.cm)
@surface   tuning.derive, tuning.genDiamond, vm:setGridSize, tuning.stepToMidi, tuning.scalaPitch, vm:retune, ec:setSelection, cm:set, cm:getAt
@harness   mk{seed.notes}

# Intent
  Retune: with no target tv:retune(slots) runs every note in scope through
  tuning.snap and writes the pair back, strength being how far of the way there
  it actually lands, and remembers the target and key on the take. The notation
  is a twelve-note quarter-comma meantone MOS, so a step's seat carries a detune
  of its own and the window is asymmetric (+38.0 / -58.6 either side of step 1).
  
  With a target it is the solve: the scope's notes grouped into strands by
  step-class, shortlisted from the notation and the target, and handed to
  sonority.solveToPoints. Those cases write a dominant seventh under a 12-EDO notation
  against the 7-limit diamond at odd limit 9 -- the chord the pull is calibrated
  on (design/adaptive-tuning.md § Harmonic lock) -- and a tritone against the
  5-limit diamond at odd limit 15, the hole that refuses a solve.

# Helpers
  @fn mk(harness, notes, temper, tempers)  @ 35-43
  @fn note(ppq, pitch, detune)  @ 45-48
  @fn lane1(h)  @ 50-54
  @fn cell(h, row)  @ 56
  @fn near(a, b, msg)  @ 58-60
  @fn seat(step, oct)  @ 63
      -- Seat of (step, octave) under MEAN, as the spec's expectation frame.
  @fn c7()  @ 66-68
      -- The C7 the pull is calibrated on, written at 12-EDO.
  @fn chordAt(h, row)  @ 71-78
      -- The chord at a row, as detune by written pitch: every chan-1 note lane at once.
  @fn offset(token, semitones)  @ 81
      -- The detune a target point lands as, seated on the 12-EDO note it is written on.

# Cases
  @case 'retune(all) seats an off-step note on its own step'  [harness]  @ 85-94
  @case 'a note past the half-way point lands on its neighbour'  [harness]  @ 98-107
  @case 'a note inside the window keeps its step'  [harness]  @ 111-118
  @case 'a note already on its step is left where it is'  [harness]  @ 122-130
  @case 'a selection confines the snap to the notes inside it'  [harness]  @ 134-143
  @case 'half strength closes half the distance, and again on the next run'  [harness]  @ 147-157
  @case 'a blend below full strength is re-seated on the nearest semitone'  [harness]  @ 161-171
  @case 'zero strength moves nothing, not even the written pitch'  [harness]  @ 175-183
  @case 'retune remembers the target and the key on the take'  [harness]  @ 187-201
  @case 'retune with no target forgets the one the take carried'  [harness]  @ 205-211
  @case 'a dominant seventh takes the otonal seventh the diamond offers'  [harness]  @ 215-225
  @case 'above the crossing the seventh gives up the otonal tuning'  [harness]  @ 229-237
  @case 'an octave doubling is seated in its own register, and moves no answer'  [harness]  @ 241-251
  @case 'a step the target leaves nowhere to go refuses the solve and names it'  [harness]  @ 255-263
  @case 'widened, the refusing class takes the point the music around it wants'  [harness]  @ 267-286

